pub(crate) fn task_completion_success(task: &BenchmarkTaskDescriptor, run: &AgentRun) -> bool {
    run.state == AgentRunState::Completed
        && completion_report_satisfies_task(task, &run.completion, run.validation_attempts.len())
        && task_specific_evidence_satisfied(task.kind, run)
}

fn task_specific_evidence_satisfied(kind: BenchmarkTaskKind, run: &AgentRun) -> bool {
    match kind {
        BenchmarkTaskKind::ReadQuestion => false,
        BenchmarkTaskKind::ProjectInspection => {
            run.audit.code_changes == 0
                && run.audit.raw_workspace_operations == 0
                && run.events.iter().any(|event| {
                    matches!(&event.evidence, Some(AgentEventEvidence::ToolAction { tool, success, .. })
                        if *success != Some(false) && benchmark_authoring_read_tool(tool))
                })
        }
        BenchmarkTaskKind::CodeImplementation => {
            run.audit.code_changes > 0
                && run.completion.source_validation == CompletionStatus::Passed
        }
        BenchmarkTaskKind::TypedAuthoringMutation => {
            run.audit.authoring_operations > 0
                && run.audit.raw_workspace_operations == 0
                && run.events.iter().any(|event| {
                    matches!(&event.evidence, Some(AgentEventEvidence::ToolAction { tool, success, .. })
                        if *success != Some(false) && benchmark_authoring_write_tool(tool))
                })
        }
        BenchmarkTaskKind::ValidationRepair => {
            run.audit.code_changes > 0
                && run.validation_attempts.len() >= 2
                && run
                    .validation_attempts
                    .first()
                    .is_some_and(|attempt| attempt.status == ManagedValidationAttemptStatus::Failed)
                && run
                    .validation_attempts
                    .last()
                    .is_some_and(|attempt| attempt.status == ManagedValidationAttemptStatus::Passed)
        }
        BenchmarkTaskKind::RuntimeInteraction => {
            run.audit.managed_runtime_inputs > 0
                && run.completion.play_launch == CompletionStatus::Passed
                && run.completion.interaction_scenarios == CompletionStatus::Passed
        }
        BenchmarkTaskKind::VisualEvaluation => {
            run.completion.visual_evaluation == CompletionStatus::Passed
                && run.events.iter().any(|event| {
                    matches!(event.evidence, Some(AgentEventEvidence::CapturedFrame { .. }))
                })
        }
    }
}

fn benchmark_authoring_read_tool(tool: &str) -> bool {
    (tool.starts_with("authoring.")
        || tool.starts_with("scene.")
        || tool.starts_with("prefab.")
        || tool == "project.describe")
        && [".describe", ".inspect", ".find", ".list", ".search", ".validate", ".preview", ".schemas", ".capabilities"]
            .iter()
            .any(|suffix| tool.ends_with(suffix))
}

fn benchmark_authoring_write_tool(tool: &str) -> bool {
    (tool.starts_with("authoring.")
        || tool.starts_with("scene.")
        || tool.starts_with("prefab.")
        || tool.starts_with("vfx.")
        || tool.starts_with("behavior_tree."))
        && !benchmark_authoring_read_tool(tool)
}

fn explicit_oom_message(message: &str) -> bool {
    let message = message.to_ascii_lowercase();
    message.contains("out of memory")
        || message.contains("cuda oom")
        || message.contains("gpu oom")
        || message
            .split(|character: char| !character.is_ascii_alphanumeric())
            .any(|word| word == "oom")
}

